   "  }\n  const opciones = '<option value=\"\">— ¿De quién es? —</option>' + ASIS.usuarios.map(u =>\n    `<option value=\"${u.id}\">${escapeHtml(u.nombre)}${u.numero_empleado ? ` (No. ${escapeHtml(u.numero_empleado)})` : ''}${u.sucursal ? ` · ${escapeHtml(u.sucursal)}` : ''}</option>`).join('');\n  caja.innerHTML = ASIS.datos.codigos_sin_empleado.map(c => `\n    <div style=\"display:flex; gap:8px; align-items:center; flex-wrap:wrap; margin:4px 0;\">\n      <span style=\"min-width:200px;\">Checador <b>${escapeHtml(c.codigo)}</b>${c.nombre ? ` — ${escapeHtml(c.nombre)}` : ''} <span style=\"color:var(--muted);\">(${c.checadas} checadas)</span></span>\n      <select id=\"asis_lig_${escapeHtml(c.codigo)}\" style=\"max-width:340px; font-size:12px;\">${opciones}</select>\n      <button class=\"secondary\" style=\"font-size:11px; padding:3px 10px;\" onclick=\"asis_ligar('${escapeHtml(c.codigo)}', this)\">Ligar</button>\n    </div>`).join('');\n}\n\nasync function asis_ligar(codigo, btn) {\n  const uid = Number((document.getElementById(`asis_lig_${codigo}`) || {}).value || 0);\n  if (!uid) { alert('Elige a la persona.'); return; }\n  await conBloqueoDeBoton(btn, async () => {\n    try {\n      await api('/api/rh/asistencia/ligar-codigo', { method: 'POST', body: JSON.stringify({ codigo, usuario_id: uid }) });\n      ASIS.usuarios = null;\n      await renderAsistenciaRH();\n    } catch (e) { alert(e.message); }\n",
   "  }\n  const opciones = '<option value=\"\">— ¿De quién es? —</option>' + ASIS.usuarios.map(u =>\n    `<option value=\"${u.id}\">${escapeHtml(u.nombre)}${u.numero_empleado ? ` (No. ${escapeHtml(u.numero_empleado)})` : ''}${u.sucursal ? ` · ${escapeHtml(u.sucursal)}` : ''}</option>`).join('');\n  caja.innerHTML = ASIS.datos.codigos_sin_empleado.map((c, i) => `\n    <div style=\"display:flex; gap:8px; align-items:center; flex-wrap:wrap; margin:4px 0;\">\n      <span style=\"min-width:260px;\">${c.gente_id ? `${escapeHtml(c.checador || c.sn)}${c.checador_sucursal ? ` (${escapeHtml(c.checador_sucursal)})` : ''} · No. <b>${escapeHtml(c.codigo_checador)}</b>`\n        : `Checador <b>${escapeHtml(c.codigo)}</b>`}${c.nombre ? ` — ${escapeHtml(c.nombre)}` : ''} <span style=\"color:var(--muted);\">(${c.checadas} checadas)</span></span>\n      <select id=\"asis_lig_${i}\" style=\"max-width:340px; font-size:12px;\">${asis_opcionesUsuarios(ASIS.usuarios, null, c.nombre)}</select>\n      <button class=\"secondary\" style=\"font-size:11px; padding:3px 10px;\" onclick=\"asis_ligar(${i}, this)\">Ligar</button>\n    </div>`).join('');\n}\n\n// Sugerencia por nombre: la persona cuyo nombre se parece más al del checador.\nfunction asis_norm(t) { return String(t || '').normalize('NFD').replace(/[\\u0300-\\u036f]/g, '').toUpperCase().replace(/[^A-Z0-9 ]/g, ' ').split(/\\s+/).filter(x => x.length > 1); }\nfunction asis_sugerir(usuarios, nombre) {\n  const a = asis_norm(nombre);\n  if (!a.length) return null;\n  let mejor = null, puntos = 0;\n  for (const u of usuarios || []) {\n    const b = asis_norm(u.nombre);\n    const comunes = a.filter(x => b.includes(x)).length;\n    const p = comunes / Math.max(a.length, 1);\n    if (comunes >= Math.min(2, a.length) && p > puntos) { puntos = p; mejor = u.id; }\n  }\n  return mejor;\n}\nfunction asis_opcionesUsuarios(usuarios, seleccionado, nombreChecador) {\n  const sug = seleccionado ? null : asis_sugerir(usuarios, nombreChecador);\n  return '<option value=\"\">— ¿De quién es? —</option>' + (usuarios || []).map(u =>\n    `<option value=\"${u.id}\" ${Number(seleccionado) === u.id || (!seleccionado && sug === u.id) ? 'selected' : ''}>${!seleccionado && sug === u.id ? '⭐ ' : ''}${escapeHtml(u.nombre)}${u.numero_empleado ? ` (No. ${escapeHtml(u.numero_empleado)})` : ''}${u.sucursal ? ` · ${escapeHtml(u.sucursal)}` : ''}</option>`).join('');\n}\n\nasync function asis_ligar(i, btn) {\n  const c = ASIS.datos.codigos_sin_empleado[i];\n  const uid = Number((document.getElementById(`asis_lig_${i}`) || {}).value || 0);\n  if (!uid) { alert('Elige a la persona.'); return; }\n  await conBloqueoDeBoton(btn, async () => {\n    try {\n      if (c.gente_id) await api(`/api/rh/checadores/gente/${c.gente_id}`, { method: 'PATCH', body: JSON.stringify({ usuario_id: uid }) });\n      else await api('/api/rh/asistencia/ligar-codigo', { method: 'POST', body: JSON.stringify({ codigo: c.codigo, usuario_id: uid }) });\n      ASIS.usuarios = null;\n      await renderAsistenciaRH();\n    } catch (e) { alert(e.message); }\n"
